toolArgs.file_text:
.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #3a3d42;
    background: #36393f;
    align-items: flex-end;
}

.message-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #4a4d52;
    border-radius: 8px;
    background: #40444b;
    color: #e0e0e0;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #7289da;
}

.message-input-area textarea::placeholder {
    color: #72767d;
}

.send-btn {
    background-color: #7289da;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 18px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background-color 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background-color: #5b6eae;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

