toolArgs.file_text:
@using sv_2b2c643164204578a073d2608236be9e.Services

@* Main message area showing channel messages *@

<div class="message-area">
    <div class="message-area-header">
        <h3># @ChannelName</h3>
        <span class="channel-desc">@ChannelDescription</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ReplyCount="GetReplyCount(msg.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")" OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get => _loadingMore; set => _loadingMore = value; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnScrollToTop { get; set; }

    private bool _loadingMore;

    private int GetReplyCount(int messageId)
        => ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top triggers loading older messages
        // In a real app we'd use JS interop to check scrollTop; here we expose the callback
        // The parent handles the pagination logic via OnScrollToTop
    }
}

