toolArgs.file_text:
@using sv_2b2c643164204578a073d2608236be9e.Services

@* Collapsible right panel showing a message thread *@

<div class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <div class="quote-author">@RootMessage.Author</div>
            <div class="quote-content">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-messages">
        @foreach (var msg in ThreadMessages.Where(m => m.Id != RootMessage?.Id))
        {
            <MessageItem Message="msg"
                         ReplyCount="0"
                         OnReact="OnReact" />
        }
        @if (!ThreadMessages.Any(m => m.Id != RootMessage?.Id))
        {
            <div class="no-replies">No replies yet. Start the conversation!</div>
        }
    </div>

    <MessageInput Placeholder="Reply in thread..."
                  ButtonLabel="Reply"
                  OnSend="OnSendReply" />
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> ThreadMessages { get; set; } = new();
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #2f3136;
    border-left: 1px solid #3a3d42;
    color: #dcddde;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #3a3d42;
}

.thread-header h4 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #72767d;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: all 0.15s;
}

.close-btn:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.1);
}

.thread-root-quote {
    padding: 10px 16px;
    margin: 8px 12px;
    background: rgba(0, 0, 0, 0.15);
    border-left: 3px solid #7289da;
    border-radius: 0 6px 6px 0;
}

.quote-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #fff;
    margin-bottom: 2px;
}

.quote-content {
    font-size: 0.85rem;
    color: #b9bbbe;
    line-height: 1.3;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.no-replies {
    text-align: center;
    padding: 24px 16px;
    color: #72767d;
    font-size: 0.88rem;
}

