@page "/chat"
@using sv_2b2c643164204578a073d2608236be9e.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="chat-main @(_isThreadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <MessageArea ChannelName="@_activeChannel.Name"
                         ChannelDescription="@_activeChannel.Description"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         IsLoadingMore="_loadingMore"
                         OnOpenThread="OpenThreadAsync"
                         OnReact="HandleReactionAsync"
                         OnSendMessage="SendMessageAsync"
                         OnScrollToTop="LoadOlderMessagesAsync" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>👈 Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnSendReply="SendThreadReplyAsync"
                         OnReact="HandleReactionAsync"
                         OnClose="CloseThread" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = new();
    private int _activeChannelId;
    private Channel? _activeChannel;
    private List<Message> _messages = new();
    private Dictionary<int, int> _threadReplyCounts = new();
    private bool _loadingMore;
    private int _skip;
    private const int PageSize = 50;

    // Thread state
    private bool _isThreadOpen;
    private int _threadRootId;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _skip = 0;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        _channels = await ChatService.GetChannelsAsync(); // Refresh unread counts
        await ComputeThreadReplyCountsAsync();
        CloseThread();
    }

    private async Task ComputeThreadReplyCountsAsync()
    {
        _threadReplyCounts.Clear();
        foreach (var msg in _messages)
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            var replyCount = thread.Count(t => t.Id != msg.Id);
            if (replyCount > 0)
                _threadReplyCounts[msg.Id] = replyCount;
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_loadingMore || _activeChannel is null) return;
        _loadingMore = true;
        _skip += PageSize;
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _skip, PageSize);
        if (older.Count > 0)
        {
            older.AddRange(_messages);
            _messages = older;
        }
        _loadingMore = false;
    }

    private async Task SendMessageAsync(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadRootMessage = _threadMessages.FirstOrDefault();
        _isThreadOpen = true;
    }

    private void CloseThread()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadMessages = new();
    }

    private async Task SendThreadReplyAsync(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootId);
        _threadMessages.Add(msg);

        // Update the reply count for the root message
        _threadReplyCounts[_threadRootId] = _threadMessages.Count(m => m.Id != _threadRootId);
    }

    private async Task HandleReactionAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to show updated reactions
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _skip + PageSize);

        if (_isThreadOpen)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootId);
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background-color: #36393f;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #72767d;
    font-size: 1.1rem;
}

